WITH filtered_subscriptions AS (SELECT * FROM subscriptions WHERE (status = 'ACTIVE' AND monthly_fee >= 80) OR start_date <= '2024-08-14'), end_month_summary AS (SELECT DATE_TRUNC('MONTH', end_date) AS end_month, SUM(CASE WHEN status = 'PAUSED' THEN monthly_fee ELSE 0 END) AS paused_monthly_fee FROM filtered_subscriptions GROUP BY DATE_TRUNC('MONTH', end_date)) SELECT * FROM end_month_summary WHERE paused_monthly_fee < 75 ORDER BY end_month
